command:
$ErrorActionPreference = 'Stop'
$repo = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
if ([string]::IsNullOrWhiteSpace($repo)) { throw 'DCOIR_REPO_ROOT is unavailable' }
Set-Location $repo
$branch = 'test/codex-review-canary-20260912'
$expected = 'd12e0c0fec119c6356fe2e3e3bf1bbc748438b27'
& git fetch --no-tags origin "+refs/heads/$branch`:refs/remotes/origin/$branch"
if ($LASTEXITCODE -ne 0) { throw 'Failed to fetch disposable canary branch' }
$actual = (& git rev-parse "refs/remotes/origin/$branch").Trim()
if ($LASTEXITCODE -ne 0 -or $actual -ne $expected) { throw "Canary branch head drift: expected $expected but observed $actual" }
& git push origin --delete $branch
if ($LASTEXITCODE -ne 0) { throw 'Failed to delete disposable canary branch' }
$remaining = @(& git ls-remote --heads origin "refs/heads/$branch")
if ($LASTEXITCODE -ne 0) { throw 'Failed to verify remote branch deletion' }
if ($remaining.Count -ne 0) { throw 'Disposable canary branch still exists after deletion push' }
Write-Host 'ISSUE466_CODEX_CANARY_BRANCH_DELETE_PASS'
